72	@RestController
73	@CrossOrigin(exposedHeaders = "errors, content-type")
74	@RequestMapping("/api")
75	public class OwnerRestControllerV1 implements OwnersApi {
76	
77	    private final ClinicService clinicService;
78	
79	    private final OwnerMapper ownerMapper;
80	
81	    private final PetMapper petMapper;
82	
83	    private final VisitMapper visitMapper;
84	
85	    private final OwnerRequestValidator ownerRequestValidator;
86	
87	    private final PostcodeValidator postcodeValidator;
88	
89	    private final DuplicateOwnerValidator duplicateOwnerValidator;
90	
91	    private final PossibleDuplicateDetector possibleDuplicateDetector;
92	
93	    private final CityOwnerLimitValidator cityOwnerLimitValidator;
94	
95	    private final CityCapacityWarningEvaluator cityCapacityWarningEvaluator;
96	
97	    private final DailyOwnerLimitValidator dailyOwnerLimitValidator;
