108	
109	    private final MemberIdGenerator memberIdGenerator;
110	
111	    private final HouseholdIdGenerator householdIdGenerator;
112	
113	    private final HouseholdSizeCalculator householdSizeCalculator;
114	
115	    private final MembershipLevelCapCalculator membershipLevelCapCalculator;
116	
117	    private final OwnerAuditLogger ownerAuditLogger;
118	
119	    private final BulkSignupWarningEvaluator bulkSignupWarningEvaluator;
120	
121	    private final OwnerCreationIdempotencyStore idempotencyStore;
122	
123	    public OwnerRestControllerV1(ClinicService clinicService,
124	                                 OwnerMapper ownerMapper,
125	                                 PetMapper petMapper,
126	                                 VisitMapper visitMapper,
127	                                 OwnerRequestValidator ownerRequestValidator,
128	                                 PostcodeValidator postcodeValidator,
129	                                 DuplicateOwnerValidator duplicateOwnerValidator,
130	                                 PossibleDuplicateDetector possibleDuplicateDetector,
131	                                 CityOwnerLimitValidator cityOwnerLimitValidator,
132	                                 CityCapacityWarningEvaluator cityCapacityWarningEvaluator,
133	                                 DailyOwnerLimitValidator dailyOwnerLimitValidator,
134	                                 RegistrationDateValidator registrationDateValidator,
135	                                 TelephoneNormalizer telephoneNormalizer,
136	                                 EmailNormalizer emailNormalizer,
137	                                 DisposableEmailDomainValidator disposableEmailDomainValidator,
138	                                 AddressFormNormalizer addressFormNormalizer,
139	                                 MemberIdGenerator memberIdGenerator,
140	                                 HouseholdIdGenerator householdIdGenerator,
141	                                 HouseholdSizeCalculator householdSizeCalculator,
142	                                 MembershipLevelCapCalculator membershipLevelCapCalculator,
143	                                 OwnerAuditLogger ownerAuditLogger,
144	                                 BulkSignupWarningEvaluator bulkSignupWarningEvaluator,
145	                                 OwnerCreationIdempotencyStore idempotencyStore) {
146	        this.clinicService = clinicService;
147	        this.ownerMapper = ownerMapper;
148	        this.petMapper = petMapper;
149	        this.visitMapper = visitMapper;
150	        this.ownerRequestValidator = ownerRequestValidator;
151	        this.postcodeValidator = postcodeValidator;
152	        this.duplicateOwnerValidator = duplicateOwnerValidator;
153	        this.possibleDuplicateDetector = possibleDuplicateDetector;
154	        this.cityOwnerLimitValidator = cityOwnerLimitValidator;
155	        this.cityCapacityWarningEvaluator = cityCapacityWarningEvaluator;
156	        this.dailyOwnerLimitValidator = dailyOwnerLimitValidator;
157	        this.registrationDateValidator = registrationDateValidator;
158	        this.telephoneNormalizer = telephoneNormalizer;
159	        this.emailNormalizer = emailNormalizer;
160	        this.disposableEmailDomainValidator = disposableEmailDomainValidator;
161	        this.addressFormNormalizer = addressFormNormalizer;
162	        this.memberIdGenerator = memberIdGenerator;
163	        this.householdIdGenerator = householdIdGenerator;
164	        this.householdSizeCalculator = householdSizeCalculator;
165	        this.membershipLevelCapCalculator = membershipLevelCapCalculator;
166	        this.ownerAuditLogger = ownerAuditLogger;
167	        this.bulkSignupWarningEvaluator = bulkSignupWarningEvaluator;
168	        this.idempotencyStore = idempotencyStore;
169	    }
170	
171	    /**
172	     * Map an owner to its DTO and stamp the current warnings onto it, so every single-owner
173	     * response reflects whether more than 80 owners have been created today and whether the
174	     * owner's city is approaching its capacity limit.
175	     */
176	    private OwnerDto toOwnerDto(Owner owner) {
177	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
178	        ownerDto.setBulkSignupWarning(this.bulkSignupWarningEvaluator.isBulkSignupInEffect());
179	        ownerDto.setCapacityWarning(this.cityCapacityWarningEvaluator.isApproachingCapacity(owner.getCity()));
180	        return ownerDto;
181	    }
182	
183	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
184	    @Override
185	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
186	        Collection<Owner> owners;
187	        if (lastName != null) {
188	            owners = this.clinicService.findOwnerByLastName(lastName);
189	        } else {
190	            owners = this.clinicService.findAllOwners();
191	        }
192	        if (owners.isEmpty()) {
193	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
194	        }
195	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
196	    }
197	
198	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
199	    @Override
200	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
201	        Owner owner = this.clinicService.findOwnerById(ownerId);
202	        if (owner == null) {
203	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
204	        }
205	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
206	    }
207	
208	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
209	    @Override
210	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
211	        if (StringUtils.hasText(idempotencyKey)) {
212	            Optional<Owner> alreadyCreated = this.idempotencyStore.find(idempotencyKey)
213	                .map(this.clinicService::findOwnerById);
214	            if (alreadyCreated.isPresent()) {
215	                return new ResponseEntity<>(toOwnerDto(alreadyCreated.get()), HttpStatus.OK);
216	            }
217	        }
218	        Owner owner = createOwner(ownerFieldsDto);
219	        if (StringUtils.hasText(idempotencyKey)) {
220	            this.idempotencyStore.remember(idempotencyKey, owner.getId());
221	        }
222	        HttpHeaders headers = new HttpHeaders();
223	        headers.setLocation(UriComponentsBuilder.newInstance()
224	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
225	        return new ResponseEntity<>(toOwnerDto(owner), headers, HttpStatus.CREATED);
226	    }
227	
228	    /**
229	     * Apply every create-time rule to the submitted fields and persist the resulting owner.
230	     */
231	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
232	        this.addressFormNormalizer.normalize(ownerFieldsDto);
233	        this.ownerRequestValidator.validate(ownerFieldsDto);
234	        this.postcodeValidator.validate(ownerFieldsDto);
235	        this.cityOwnerLimitValidator.validate(ownerFieldsDto);
236	        this.registrationDateValidator.validate(ownerFieldsDto.getRegistrationDate());
237	        this.dailyOwnerLimitValidator.validate(ownerFieldsDto.getRegistrationDate());
238	        ownerFieldsDto.setTelephone(this.telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
239	        ownerFieldsDto.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
240	        this.disposableEmailDomainValidator.validate(ownerFieldsDto.getEmail());
241	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
242	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
243	        // The householdId is deterministic from (lastName, postcode), so every owner carries the
244	        // identifier of its household automatically.
245	        owner.setHouseholdId(
246	            this.householdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
247	        if (sharesHousehold) {
248	            // A declared household member is deliberately allowed and, being declared, is never a
249	            // suspected duplicate.
250	            owner.setPossibleDuplicate(false);
251	            owner.setPossibleDuplicateOf(null);
252	        } else {
253	            this.duplicateOwnerValidator.validate(owner);
254	            Integer possibleDuplicateOf = this.possibleDuplicateDetector.findPossibleDuplicate(owner);
255	            owner.setPossibleDuplicate(possibleDuplicateOf != null);
256	            owner.setPossibleDuplicateOf(possibleDuplicateOf);
257	        }
258	        owner.setMemberId(this.memberIdGenerator.generate(owner));
259	        owner.setNamesakeCount(
260	            (int) this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
261	        owner.setHouseholdSize(this.householdSizeCalculator.size(owner));
262	        owner.setMembershipLevelCap(this.membershipLevelCapCalculator.cap(owner));
263	        this.clinicService.saveOwner(owner);
264	        this.ownerAuditLogger.created(owner);
265	        return owner;
266	    }
267	
268	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
269	    @Override
270	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
271	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
272	        if (currentOwner == null) {
273	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
274	        }
275	        currentOwner.setAddress(ownerFieldsDto.getAddress());
276	        currentOwner.setCity(ownerFieldsDto.getCity());
277	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
278	        currentOwner.setLastName(ownerFieldsDto.getLastName());
279	        currentOwner.setTitle(ownerFieldsDto.getTitle());
280	        currentOwner.setTelephone(this.telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
281	        currentOwner.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
282	        this.clinicService.saveOwner(currentOwner);
283	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
284	    }
285	
286	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
287	    @Transactional
288	    @Override
289	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
290	        Owner owner = this.clinicService.findOwnerById(ownerId);
291	        if (owner == null) {
292	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
293	        }
294	        this.clinicService.deleteOwner(owner);
295	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
296	    }
297	
298	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
299	    @Override
300	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
301	        Owner owner = this.clinicService.findOwnerById(ownerId);
302	        if (owner == null) {
303	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
304	        }
305	        HttpHeaders headers = new HttpHeaders();
306	        Pet pet = petMapper.toPet(petFieldsDto);
307	        owner.setId(ownerId);
308	        pet.setOwner(owner);
309	        pet.getType().setName(null);
310	        this.clinicService.savePet(pet);
311	        PetDto petDto = petMapper.toPetDto(pet);
312	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
313	            .buildAndExpand(pet.getId()).toUri());
314	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
315	    }
316	
317	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
318	    @Override
319	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
320	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
321	        if (currentOwner != null) {
322	            Pet currentPet = this.clinicService.findPetById(petId);
323	            if (currentPet != null) {
324	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
325	                currentPet.setName(petFieldsDto.getName());
326	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
327	                this.clinicService.savePet(currentPet);
328	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
329	            }
330	        }
331	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
332	    }
333	
334	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
335	    @Override
336	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
337	        HttpHeaders headers = new HttpHeaders();
338	        Visit visit = visitMapper.toVisit(visitFieldsDto);
339	        Pet pet = new Pet();
340	        pet.setId(petId);
341	        visit.setPet(pet);
342	        this.clinicService.saveVisit(visit);
343	        VisitDto visitDto = visitMapper.toVisitDto(visit);
344	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
345	            .buildAndExpand(visit.getId()).toUri());
346	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
347	    }
348	
349	
350	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
351	    @Override
352	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
353	        Owner owner = this.clinicService.findOwnerById(ownerId);
354	        if (owner != null) {
355	            Pet pet = owner.getPet(petId);
356	            if (pet != null) {
357	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
358	            }
359	        }
360	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
361	    }
362	}
